+    };
+
+    await this.blockSink
+      .appendBlockOnce(input.jobId, `codex:${input.jobId}:${row.resume_count}`, {
+        kind: 'agent_prompt',
+        threadId: reviewThreadId,
+        text: task,
+        meta: {
+          codexReviewId: input.jobId,
+          agentPrompt: true,
+          reviewRound: row.resume_count,
