+  async teardown(sandbox: FeatureSandbox): Promise<void> {
+    if (!sandbox.containerId) return;
+    const info = await this.engine.inspect(sandbox.containerId);
+    await this.engine.remove(sandbox.containerId, { force: true });
+    if (info) {
