+  private augment(sandbox: FeatureSandbox, containerId: string, warm: boolean): FeatureSandbox {
+    const user = hostExecUser();
+    return {
+      ...sandbox,
+      containerId,
+      warm,
+      ...(user ? { execUser: user } : {}),
+    };
+  }
