+            parent_tool_use_id?: string | null;
+            event?: {
+              type?: string;
+              delta?: { type?: string; text?: string; thinking?: string };
+            };
+          };
+          const parent = sev.parent_tool_use_id ?? undefined;
+          const sub = parent ? { parentToolUseId: parent } : {};
+          const ev = sev.event;
+          if (ev?.type === 'content_block_delta') {
