export function useCloudLift(args: {
  app: AtlasApp
  threadId: ThreadId
  started: boolean
  projectDirectory: string
  readEvents: () => readonly Event[]
  setLocation: (location: EExecutionLocation) => void
  createBridge: (args: { url: string; token: string }) => CloudBridge
  onLifted: (session: LiftedSession) => void
}): CloudLiftControl {
  const { app, onLifted } = args
  const lifting = useRef(false)

  const handleLift = useCallback(() => {
    if (lifting.current) return

    const session = app.cloud.session()
    if (session === null) {
      notify({ key: CLOUD_LIFT_NOTICE_KEY, text: NOT_SIGNED_IN, tone: ENoticeTone.Warn })
      return
    }

    lifting.current = true
    const bridge = args.createBridge({ url: session.url, token: session.token })

    void liftToCloud({
      threadId: args.threadId,
      cwd: args.projectDirectory,
      events: args.readEvents(),
      started: args.started,
      identity: app.workspace,
      title: null,
      bridge,
      localThreads: app.threads,
      ids: app.ids,
      setLocation: args.setLocation,
      stopLocal: async () =>
        stopLocalWork({ threadId: args.threadId, shells: app.shells, services: app.services }),
      capture: ({ cwd }) => captureWorkspace({ cwd }),
      onProgress: (step: ELiftStep) =>
        notify({
          key: CLOUD_LIFT_NOTICE_KEY,
          text: liftProgressNotice(step),
          tone: ENoticeTone.Info,
          sticky: true,
        }),
    })
      .then(async (lifted) => {
        if (!lifted.ok) {
          notify({
            key: CLOUD_LIFT_NOTICE_KEY,
            text: liftFailedNotice(lifted),
            tone: ENoticeTone.Warn,
            ttlMs: NOTICE_WARN_MS,
          })
          return
        }

        const attached = cloudApp({ app, bridge, channel: lifted.channel })
        const opened = await openCloudConversation({ app: attached, threadId: args.threadId })

        notify({
          key: CLOUD_LIFT_NOTICE_KEY,
          text: liftedNotice(lifted),
          tone: ENoticeTone.Done,
        })

        onLifted({
          app: attached,
          opened,
          session: createCloudSession({
            channel: lifted.channel,
            sandboxes: bridge.sandboxes,
            onReload: () => onLifted.reload(),
          }),
          reloads: 0,
        })
      })
      .catch((error: unknown) => {
        notify({
          key: CLOUD_LIFT_NOTICE_KEY,
          text: `moving to the cloud failed — ${error instanceof Error ? error.message : String(error)}`,
          tone: ENoticeTone.Warn,
          ttlMs: NOTICE_WARN_MS,
        })
      })
      .finally(() => {
        lifting.current = false
      })
  }, [app, args, onLifted])

  return { handleLift }
}

